fn manifest_paths(manifest: &engine::AssetManifest, suffix: &str) -> Vec<PathBuf> {
    let mut paths = manifest
        .iter()
        .filter_map(|(_, entry)| {
            entry
                .path
                .to_ascii_lowercase()
                .ends_with(suffix)
                .then(|| PathBuf::from(&entry.path))
        })
        .collect::<Vec<_>>();
